export const POPULATION=1500000000;
export function grade(s){const a=Math.floor(s.day/365);if(s.stage==='preschool')return '学前启蒙';if(s.stage==='kindergarten')return ['小班','中班','大班'][Math.min(2,Math.max(0,a-3))];if(s.stage==='preparation')return '社会实践';const start={primary:6,middle:12,high:15,university:18,master:22,phd:25}[s.stage];if(start===undefined)return '';const limit={primary:6,middle:3,high:3,university:4,master:3,phd:4}[s.stage];return Math.min(limit,Math.max(1,a-start+1))+'年级';}
export function nationalStanding(s){if(s.stage==='work'&&s.progress>=1&&!s.retired&&!s.ended)return {rank:1,percent:100,label:'举国之首 · 国家主席'};const mean=s.stats.reduce((n,x)=>n+x,0)/5;let score=Math.min(.8,Math.max(0,(mean-5)/240));if(s.stage==='work')score=Math.max(score,.82+.179999*Math.min(1,s.progress));const rank=Math.max(2,Math.round(POPULATION*(1-score)**3));const percent=(1-(rank-1)/POPULATION)*100;return {rank,percent,label:percent>=99.99?'人中龙凤':percent>=99?'卓尔不群':percent>=90?'崭露头角':'平凡亦有光'};}
export {familyYear,familySummary} from './family.js?v=0.6.0';
export function avatar(s){const a=Math.floor(s.day/365),female=s.gender==='女',old=a>=60,middle=a>=40,child=a<18,baby=a<3;const hair=old?'#b9b8ad':middle?'#50504b':'#293d36',shirt=female?'#938674':'#537c70',bg=female?'#ece1d4':'#dce8dd',skin=['#eac7a4','#dfb88f','#f0d3b5'][s.avatarVariant||0];return `<svg viewBox="0 0 120 140" role="img" aria-label="${s.gender}性${baby?'婴幼儿':child?'少年':old?'老年':middle?'中年':'青年'}头像"><rect width="120" height="140" rx="16" fill="${bg}"/><circle cx="60" cy="56" r="${baby?34:child?30:28}" fill="${skin}"/>${female&&!baby?`<path d="M27 88V45C27 7 95 7 95 47V91L82 83V42C63 51 49 44 37 41V89Z" fill="${hair}"/>`:`<path d="M29 46C22 9 97 6 91 46L80 36 58 32 35 43Z" fill="${hair}"/>`}<path d="M18 140V117Q23 91 49 90L60 101 71 90Q100 94 104 117V140" fill="${shirt}"/><path d="M48 87L60 101 72 87" fill="${skin}"/><circle cx="49" cy="57" r="2.5" fill="#33433b"/><circle cx="72" cy="57" r="2.5" fill="#33433b"/><path d="M52 73Q60 79 69 72" fill="none" stroke="#9e6757" stroke-width="2" stroke-linecap="round"/>${old?'<path d="M40 63L47 65M74 65L81 62M48 79L45 83M73 79L76 83M48 49L54 48M67 48L74 49" stroke="#b58e72" fill="none"/>':''}${middle?'<g stroke="#637068" fill="none"><rect x="40" y="51" width="18" height="13" rx="5"/><rect x="64" y="51" width="18" height="13" rx="5"/><path d="M58 56H64"/></g>':''}${baby?'<ellipse cx="40" cy="69" rx="6" ry="3" fill="#e5a992" opacity=".6"/><ellipse cx="81" cy="69" rx="6" ry="3" fill="#e5a992" opacity=".6"/>':''}</svg>`;}

